CREATE TABLE boards (id INTEGER PRIMARY KEY, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE board_items (id INTEGER PRIMARY KEY, board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE, caption TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', filename TEXT, thumbnail TEXT, preview TEXT, x INTEGER NOT NULL DEFAULT 0 CHECK(x BETWEEN 0 AND 2000), y INTEGER NOT NULL DEFAULT 0 CHECK(y BETWEEN 0 AND 2000), width INTEGER NOT NULL DEFAULT 200 CHECK(width BETWEEN 100 AND 600));
CREATE TABLE weather_cache (id INTEGER PRIMARY KEY CHECK(id=1), label TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, fetched_at TEXT NOT NULL, payload TEXT NOT NULL);
